import json, math
from pathlib import Path
from pyscipopt import Model, quicksum

root = Path(__file__).parent
data = json.loads((root / 'data.json').read_text())
stations = data['stations']
ids = [s['id'] for s in stations]
K = range(data['vehicle_count'])
N = range(len(stations))
S, E, cap = 'depot_start', 'depot_end', int(data['vehicle_capacity'])

def dist(a, b):
    r = math.pi / 180
    p1, p2 = (90-float(a['latitude']))*r, (90-float(b['latitude']))*r
    t1, t2 = float(a['longitude'])*r, float(b['longitude'])*r
    c = math.sin(p1)*math.sin(p2)*math.cos(t1-t2)+math.cos(p1)*math.cos(p2)
    return math.acos(max(-1, min(1, c))) * 3960.0

def loc(node): return data['depot'] if node in (S,E) else stations[node]
arcs = [(i,j) for i in [S,*N] for j in [*N,E] if i != j and (i,j) != (S,E)]
d = {(i,j): dist(loc(i),loc(j)) for i,j in arcs}
m = Model('bike_rebalancing'); m.hideOutput()
x = {(k,i,j):m.addVar(vtype='B') for k in K for i,j in arcs}
y = {(k,i):m.addVar(vtype='B') for k in K for i in N}
o = {(k,i):m.addVar(lb=0,ub=len(stations)) for k in K for i in N}
p = {(k,i):m.addVar(vtype='I',lb=0,ub=cap) for k in K for i in N}
q = {(k,i):m.addVar(vtype='I',lb=0,ub=cap) for k in K for i in N}
z = {(k,i):m.addVar(vtype='B') for k in K for i in N}
l = {(k,i):m.addVar(vtype='I',lb=0,ub=cap) for k in K for i in N}
sl = {k:m.addVar(vtype='I',lb=0,ub=cap) for k in K}
el = {k:m.addVar(vtype='I',lb=0,ub=cap) for k in K}
u = {i:m.addVar(vtype='I',lb=0) for i in N}
for k in K:
    m.addCons(quicksum(x[k,S,i] for i in N)==1)
    m.addCons(quicksum(x[k,i,E] for i in N)==1)
    for i in N:
        m.addCons(quicksum(x[k,a,i] for a in [S,*N] if a!=i)==y[k,i])
        m.addCons(quicksum(x[k,i,b] for b in [*N,E] if b!=i)==y[k,i])
        m.addCons(o[k,i]>=y[k,i]); m.addCons(o[k,i]<=len(N)*y[k,i])
        m.addCons(p[k,i]<=cap*z[k,i]); m.addCons(p[k,i]<=cap*y[k,i])
        m.addCons(q[k,i]<=cap*(y[k,i]-z[k,i]))
        net=p[k,i]-q[k,i]
        for sign in (-1,1):
            m.addCons(sign*(l[k,i]-sl[k]-net) <= cap*(1-x[k,S,i]))
            m.addCons(sign*(el[k]-l[k,i]) <= cap*(1-x[k,i,E]))
    for i in N:
        for j in N:
            if i==j: continue
            m.addCons(o[k,j]>=o[k,i]+1-len(N)*(1-x[k,i,j]))
            for sign in (-1,1):
                m.addCons(sign*(l[k,j]-l[k,i]-(p[k,j]-q[k,j])) <= cap*(1-x[k,i,j]))
for i,s in enumerate(stations):
    target=int(s['net_rebalancing_target']); P=quicksum(p[k,i] for k in K); Q=quicksum(q[k,i] for k in K)
    if target>=0:
        m.addCons(Q==0); m.addCons(P<=min(target,int(s['initial_bikes']))); m.addCons(u[i]==target-P)
    else:
        m.addCons(P==0); m.addCons(Q<=min(-target,int(s['station_capacity'])-int(s['initial_bikes']))); m.addCons(u[i]==-target-Q)
m.setObjective(quicksum(d[i,j]*x[k,i,j] for k in K for i,j in arcs)+float(data['penalty_weight'])*quicksum(u.values()), 'minimize')
m.setParam('limits/time',300.0); m.optimize()
if m.getNSols()==0: raise RuntimeError(f'no solution: {m.getStatus()}')
def val(v): return int(round(m.getVal(v)))
vehicles=[]
for k in K:
    route=[]; cur=S
    while cur!=E:
        cur=next(j for i,j in arcs if i==cur and m.getVal(x[k,i,j])>.5)
        if cur!=E: route.append(cur)
    vehicles.append({'vehicle_id':k+1,'start_load':float(val(sl[k])),'route':[S,*[ids[i] for i in route],E], 'stops':[{'station_id':ids[i],'bikes_picked_up':float(val(p[k,i])),'bikes_dropped_off':float(val(q[k,i])),'load_after_stop':float(val(l[k,i]))} for i in route], 'end_load':float(val(el[k]) )})
station_reports=[]
for i,s in enumerate(stations):
    P=sum(val(p[k,i]) for k in K); Q=sum(val(q[k,i]) for k in K)
    station_reports.append({'station_id':s['id'],'net_rebalancing_target':float(s['net_rebalancing_target']),'total_bikes_picked_up':float(P),'total_bikes_dropped_off':float(Q),'net_bike_change':float(P-Q),'unmet_rebalancing_amount':float(val(u[i]))})
travel=sum(d[i,j]*m.getVal(x[k,i,j]) for k in K for i,j in arcs)
total_unmet=sum(s['unmet_rebalancing_amount'] for s in station_reports); penalty=float(data['penalty_weight'])*total_unmet
report={'summary':{'objective':travel+penalty,'travel_distance_miles':travel,'unmet_rebalancing_penalty':penalty,'total_unmet_rebalancing_amount':total_unmet},'vehicles':vehicles,'stations':station_reports}
(root/'report.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report,indent=2))
